#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=10

# Run from the repo root so fly.toml and npm scripts resolve.
cd "$(dirname "${BASH_SOURCE[0]}")/.."

# Values the rest of the repo already fixes: keep them in sync.
APP=$(sed -n 's/^app = "\(.*\)"$/\1/p' fly.toml)  # fly.toml
DOMAIN="jonpark.dev"
SECRET_NAME="FLY_API_TOKEN"                        # .github/workflows/deploy.yml
# Text the home page always shows: the tagline in src/pages/index.astro
# (test/home.test.ts checks the built home page contains it).
HOME_PAGE_TEXT="A garden of system design notes, kept in service of interview prep."

banner "jonpark.dev hosting: Fly.io behind Cloudflare"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools: flyctl and gh"
say "You need flyctl (Fly's CLI) and gh (GitHub's CLI, logged in to this repo)."
if command -v flyctl >/dev/null 2>&1; then note "flyctl found: $(command -v flyctl)"
else
  warn "flyctl not found."
  step "Install it: brew install flyctl   (or: curl -L https://fly.io/install.sh | sh)"
fi
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then note "gh found and logged in."
else
  warn "gh missing or not logged in."
  step "Install it (brew install gh), then run: gh auth login"
fi
pause "Press Enter once both are installed and gh is logged in."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Optional: local smoke run of the container"
say "Checks the image serves the built site on port 8080. Needs Docker."
if command -v docker >/dev/null 2>&1 && confirm "Build and run the image locally now?"; then
  npm run build
  docker build -t "$APP" .
  cid=$(docker run -d --rm -p 8080:8080 "$APP")
  sleep 2
  if curl -fsS http://localhost:8080 | grep -qF "$HOME_PAGE_TEXT"; then
    printf '  %s✓ local container serves the home page%s\n' "$GREEN" "$RESET"
  else
    warn "local container did not return the home page"
    SKIPPED+=("Local smoke run failed: check docker logs")
  fi
  docker stop "$cid" >/dev/null || true
else
  note "Skipped. (No Docker? The GitHub Action builds the image anyway.)"
  SKIPPED+=("Local smoke run: npm run build && docker build -t $APP . && docker run --rm -p 8080:8080 $APP, then curl localhost:8080")
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Fly: log in"
say "This opens Fly in your browser. Sign up or log in, and add a card if asked"
say "(one always-on shared-cpu-1x machine costs about \$2 a month)."
if confirm "Run 'flyctl auth login' now?"; then
  flyctl auth login || warn "login failed; run 'flyctl auth login' yourself"
fi
note "Logged in as: $(flyctl auth whoami 2>/dev/null || echo '(not logged in)')"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Fly: create the app"
say "Creates the Fly app '$APP' (the name in fly.toml). Fly app names are global;"
say "if it's taken, change 'app' in fly.toml, commit, and re-run this wizard."
if flyctl status -a "$APP" >/dev/null 2>&1; then
  note "App '$APP' already exists. Nothing to do."
elif confirm "Create Fly app '$APP'?"; then
  flyctl apps create "$APP" || warn "couldn't create '$APP'"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub: Fly deploy token as a secret"
say "Creates a deploy token scoped to '$APP' and stores it as the GitHub"
say "Actions secret $SECRET_NAME, which the Deploy workflow uses."
if confirm "Create the token and set the $SECRET_NAME secret?"; then
  FLY_TOKEN=$(flyctl tokens create deploy -a "$APP" --name "github-actions") || FLY_TOKEN=""
  if [[ -n "$FLY_TOKEN" ]]; then
    set_secret "$SECRET_NAME" "$FLY_TOKEN"
  else
    warn "token creation failed"
    SKIPPED+=("GitHub secret $SECRET_NAME: flyctl tokens create deploy -a $APP | gh secret set $SECRET_NAME")
  fi
  unset FLY_TOKEN
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "First deploy: push to main"
say "The Deploy workflow runs on every push to main: it builds the site,"
say "packages dist/ into the image and runs 'flyctl deploy'."
step "Merge this work into main and push (git push origin main)."
REPO_URL=$(gh repo view --json url -q .url 2>/dev/null || true)
[[ -n "$REPO_URL" ]] && open_url "$REPO_URL/actions/workflows/deploy.yml"
step "Wait for the Deploy run to go green."
pause "Press Enter once the run has succeeded."
say "Fly should now run exactly one shared-cpu-1x machine:"
flyctl scale show -a "$APP" || warn "couldn't read the scale"
step "Check: COUNT 1, shared-cpu-1x, 256MB. Then open https://$APP.fly.dev"
open_url "https://$APP.fly.dev"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Fly: certificate for $DOMAIN"
say "Fly needs its own certificate for $DOMAIN so Cloudflare's Full (strict)"
say "mode can trust the origin. Behind the Cloudflare proxy, Fly validates it"
say "through a DNS record (_acme-challenge), which you add in the next stage."
flyctl certs show "$DOMAIN" -a "$APP" >/dev/null 2>&1 || flyctl certs add "$DOMAIN" -a "$APP" || warn "couldn't add the certificate"
flyctl certs setup "$DOMAIN" -a "$APP" || flyctl certs show "$DOMAIN" -a "$APP" || true
step "Keep this output visible: note the _acme-challenge CNAME target it shows."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: DNS records"
open_url "https://dash.cloudflare.com/"
step "Pick the $DOMAIN zone → DNS → Records."
step "Delete the leftover record for $DOMAIN (name '@') causing the 520 error:"
note "   the existing A, AAAA or CNAME on the apex that points at the old host."
step "Add: CNAME, name '@', target '$APP.fly.dev', Proxy status ON (orange cloud)."
note "   (Cloudflare flattens a CNAME on the apex; that's expected.)"
step "Add: CNAME, name '_acme-challenge', target = the value Fly showed in stage 7,"
step "     Proxy status OFF (grey cloud, DNS only)."
pause "Press Enter once the records are saved."
warn "If the zone's SSL mode is still Flexible, https://$DOMAIN now loops forever:"
note "   Cloudflare reaches Fly over plain HTTP and fly.toml's force_https redirects it"
note "   back to HTTPS. That's expected until stage 9 sets Full (strict)."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Wait for the Fly certificate, then Cloudflare SSL: Full (strict)"
say "Checking the certificate (DNS can take a few minutes; re-check as needed)."
while true; do
  flyctl certs check "$DOMAIN" -a "$APP" || true
  confirm "Is the certificate issued? (N waits 15s and re-checks)" && break
  sleep 15
done
say "Only switch to Full (strict) once the cert is issued, otherwise visitors get a 526."
open_url "https://dash.cloudflare.com/"
step "$DOMAIN zone → SSL/TLS → Overview → Configure → Full (strict) → Save."
pause "Press Enter once SSL mode is Full (strict)."

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Check: https://$DOMAIN"
say "Fetching https://$DOMAIN with certificate verification on…"
if curl -fsS "https://$DOMAIN" | grep -qF "$HOME_PAGE_TEXT"; then
  printf '  %s✓ https://%s serves the home page with a valid certificate%s\n' "$GREEN" "$DOMAIN" "$RESET"
else
  warn "https://$DOMAIN didn't return the home page yet."
  note "Retry: curl -v https://$DOMAIN   (520 = old record still there, 526 = Fly cert not issued yet)"
  note "Past Sat Nov 14 noon and still not live? See docs/hosting.md for the Cloudflare Pages fallback."
  SKIPPED+=("Live check: curl https://$DOMAIN")
fi
pause

finish
}

run_wizard "$@"; exit
